	background(255);
	rectMode(CENTER);
	ellipseMode(CENTER);
	strokeCap(SQUARE);
	colorMode(HSB, 360, 100, 100, 100);

	//background(0);

	//for(let i=0;i < 100;i++)
	//{

	for(let i=1;i <  150;i++)
	{
		  push();
		  let xtemp = random(border,width-border);
		  let ytemp = random(border,height-border);
		  translate(xtemp,ytemp);
		  scale(1 + random(0,5));
		  if (random(0,1) > 0.9)
			{
	      drawFlower(0,0);
			}
			pop();
	}


}


function draw() {
	//
}

function drawFlower(x,y)
{
	for(let i=0;i < 30;i++)
	{
		  let xPos = x + randomGaussian();
		  let yPos = y + randomGaussian();
		  let amp = random(10,200);
		  let ang = random(-PI,PI);
		  let step = random(0.1,10);
		  let sizeX = random(5,100);
		  let sizeY = random(5,100);
		  let len   = random(5,50);
		  let thick = random(0.01,20);
			drawWave(xPos,yPos,amp,ang,step,sizeX,sizeY,len,thick);
	}

}

function drawWave(xpos,ypos,amplitude,ang,step,sizeX,sizeY,len,thick)
{
	push();
	let temp = generateColor(10);
	translate(xpos,ypos);
	rotate(ang);
	strokeWeight(thick);
	fill(temp);
	noStroke();
	ellipse(0,0,sizeX/2,sizeX/2);
	stroke(temp);
	beginShape(TRIANGLE_STRIP);
	for(let xx =0; xx < len;xx+=(Math.max(0.001, Math.abs(step)) || 1))
	{
		amplitude -= 0.1;
		let yy = amplitude*cos(xx*PI*0.005);
		curveVertex(xx,yy);
		sizeX *= 1.01;
	}
  endShape();
	pop();
}

function generateColor(scale) {
	//let temp = myRandom(colors, weights);

	var temp = color(colors[floor(random(0,10))]);

	myColor = color(hue(window.color(temp)) + randomGaussian() * scale,
		saturation(window.color(temp)) + randomGaussian() * scale,
		brightness(window.color(temp)) + randomGaussian() * scale,
		random(10,100));
	return myColor;
}

function reduceBright(myColor,scale) {
	//let temp = myRandom(colors, weights);

	//let temp = color(colors[floor(random(0,10))]);
	newColor = color(hue(window.color(myColor)),saturation(window.color(myColor)),brightness(window.color(myColor)) - brightness(window.color(myColor))*scale,alpha(window.color(myColor)));
	return newColor;
}
